import {SECTIONS,DEFAULT_SYMBOLS,escapeHTML as h,dayKey,sessionAt,clockAt,filterTrades,statistics,accountStats,dateRange,validateState,validateFeed} from './core.js';
import {load,save} from './store.js';
import {download,exportReport} from './export.js';
import {fetchDollarRate,fetchPublicMarket,fetchEconomicCalendar} from './rates.js';
const brandIcon='./assets/icon-192.png';
function marketWidgetURL(theme,refresh='') {const config={width:'100%',height:340,colorTheme:theme==='dark'?'dark':'light',locale:'en',showSymbolLogo:true,isTransparent:false,symbolsGroups:[{name:'MET · FOREX & GOLD',symbols:state.watchSymbols.map(name=>({name,displayName:name.split(':')[1]}))}]};return 'https://www.tradingview-widget.com/embed-widget/market-quotes/?locale=en'+(refresh?'&refresh='+encodeURIComponent(refresh):'')+'#'+encodeURIComponent(JSON.stringify(config));}
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',money:'M3 5h18v14H3zM3 9h18M15 13h3',mind:'M9 18h6M9 21h6M8 15a7 7 0 1 1 8 0v3H8z',technical:'M4 20V4M4 20h17M7 15l4-5 4 2 5-7',plan:'M4 4h6v6H4zM14 14h6v6h-6zM10 7h7v7',journal:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',accounts:'M4 21v-9h16v9M2 8l10-5 10 5H2M8 12v9M16 12v9',plus:'M12 5v14M5 12h14',arrow:'M18 12H6m5-5-5 5 5 5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12M6 18 18 6',edit:'m4 16 12-12 4 4L8 20H4v-4M14 6l4 4',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',menu:'M4 6h16M4 12h16M4 18h16'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.journal}"/></svg>`;
const nf=new Intl.NumberFormat('fa-IR',{maximumFractionDigits:2});
let state,tab='home',filters={account:'',...dateRange('month')},checklistCompare=['M','D','H1'],busy=false,feedBusy=false,rateBusy=false,rateError='',toastTimer;
let selectedAccount='',educationCategory='technical',marketBusy=false,marketError='',calendarBusy=false,calendarError='',calendarDay='',calendarItems=[];
const root=document.getElementById('app'),modal=document.getElementById('modal');
const n=v=>nf.format(v);
const accountName=id=>state.accounts.find(a=>a.id===id)?.name||'حساب حذف‌شده';
function rialHint(v){return state.settings.rate?`${n(Number(v)*state.settings.rate*10)} ریال${Date.now()-Date.parse(state.settings.rateAt)>172800000?' · نرخ قدیمی':''}`:'تبدیل ریال: نرخ دلار هنوز دریافت نشده';}
function money(v){return `<bdi>$${new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(v)}</bdi><small class="conversion">${rialHint(v)}</small>`;}
function plainMoney(v){return v;}
const currencyTitle=()=>'USD';
const persianDate=date=>new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeZone:'UTC'}).format(new Date(date+'T12:00:00Z'));
const empty=(text,action='',label='')=>`<div class="empty">${icon('journal')}<p>${text}</p>${action?`<button class="text-button" data-action="${action}">${label} ${icon('arrow')}</button>`:''}</div>`;
const btn=(action,label,cls='button',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const exportButtons=type=>`<div class="export-buttons" aria-label="خروجی گزارش">${['xlsx','docx','pdf'].map(f=>btn('export',f==='xlsx'?'Excel':f==='docx'?'Word':'PDF','small-button',`data-type="${type}" data-format="${f}"`)).join('')}</div>`;
const sectionHeader=(title,other='')=>`<div class="section-head"><h2>${title}</h2>${other}</div>`;
function toast(message){clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
let saveQueue=Promise.resolve();
function commit(mutator){const operation=saveQueue.then(async()=>{const next=JSON.parse(JSON.stringify(state));mutator(next);await save(next);state=next;render();});saveQueue=operation.catch(()=>{});return operation;}
function rateStatus(){const {rate,rateAt,rateSource,autoRate}=state.settings;const age=Date.now()-Date.parse(rateAt);const source=rateSource==='iran-market'?'آنلاین · Iran Market / TGJU':rateSource==='priceto.day'?'منبع قبلی · priceto.day':rateSource==='custom'?'API اختصاصی':'دستی';const base=rate?`هر دلار ${n(rate)} تومان · ${source} · ${h(new Date(rateAt).toLocaleString('fa-IR'))}${age>48*3600000?' · نرخ قدیمی':''}`:'هنوز نرخ تبدیل ثبت نشده است';return `${base}${rateBusy?' · در حال دریافت…':rateError?' · '+h(rateError):autoRate!==false?' · دریافت خودکار فعال':''}`;}
function updateRateStatus(){const el=document.getElementById('rate-status');if(el)el.innerHTML=rateStatus();}
async function refreshDollarRate(manual=false){if(rateBusy||(!manual&&state.settings.autoRate===false))return;if(!navigator.onLine){rateError='آفلاین؛ نرخ ذخیره‌شده تغییر نکرد';updateRateStatus();return;}rateBusy=true;rateError='';updateRateStatus();const previousAt=state.settings.rateAt;try{const result=await fetchDollarRate();if(!manual&&state.settings.autoRate===false)return;if(state.settings.rateAt!==previousAt&&state.settings.rateSource==='manual')return;await commit(s=>Object.assign(s.settings,result));if(manual)toast('نرخ بازار آزاد به تومان دریافت شد؛ تبدیل مبالغ آماده است.');}catch(error){rateError=error.name==='AbortError'?'دریافت نرخ زمان‌بر شد؛ نرخ قبلی حفظ شد':error instanceof TypeError?'اتصال به منبع نرخ ممکن نیست؛ نرخ قبلی حفظ شد':error.message;if(manual)toast(rateError);}finally{rateBusy=false;updateRateStatus();}}
function nav(){return SECTIONS.map(([id,title])=>`<button class="nav-item ${tab===id?'active':''}" data-tab="${id}" ${tab===id?'aria-current="page"':''}>${icon(id)}<span>${title}</span>${tab===id?'<span class="nav-dot"></span>':''}</button>`).join('');}
function render(){const current=SECTIONS.find(s=>s[0]===tab),dark=state.settings.theme==='dark';document.documentElement.setAttribute('data-theme',dark?'dark':'light');root.innerHTML=`<aside class="sidebar"><a class="brand sidebar-logo" href="#home" aria-label="خانه MET"><img src="${brandIcon}" alt="نشان MET" width="88" height="88"></a><div class="nav-label">فضای معاملاتی شما</div><nav aria-label="بخش‌های برنامه">${nav()}</nav><div class="sidebar-bottom"><div class="local-badge"><span class="status-dot"></span> دفتر شخصی، روی دستگاه شما</div>${btn('settings',icon('settings')+' تنظیمات و پشتیبان','nav-item')}<a href="./guide.html" class="guide-link" target="_blank" rel="noopener">راهنمای استفاده و نصب ${icon('arrow')}</a><div class="version"><span>MET WORKSPACE</span><span>V 1.8</span></div></div></aside><div class="workspace"><header class="topbar"><div class="page-context">${current[1]}<span class="connection"><i class="status-dot"></i><span id="network-label">${navigator.onLine?'آمادهٔ ثبت':'حالت آفلاین'}</span></span></div><a class="header-wordmark" href="#home" aria-label="MET — THE PERSIAN HUNTER"><strong>MET<span>JOURNAL</span></strong><small>THE PERSIAN HUNTER</small></a><div class="top-actions">${btn('theme',dark?'حالت روز':'حالت شب','theme-button',`aria-pressed="${dark}"`)}${btn('settings','تنظیمات','mobile-settings small-button')}</div></header><main id="main" tabindex="-1">${tab==='home'?home():page()}</main></div>`;updateClock();inputHints();}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">دفتر شخصی معامله‌گر</div><h1>${title}</h1><p>${subtitle}</p></div>${action}</div>`;}
function home(){return `${heading('هر معامله، یک قدم آگاهانه‌تر','به فضای معاملاتی خودت خوش آمدی. امروز را با یک پلن روشن شروع کن.',btn('new-trade',icon('plus')+' ثبت معامله','button primary'))}<div class="hero-grid"><section class="hero"><div class="hero-copy"><span class="hero-kicker">DISCIPLINE IS YOUR EDGE</span><h2>بازار را نمی‌توان کنترل کرد؛<br>تصمیم‌هایت را چرا.</h2><p>ثبت کن، مرور کن و نسخهٔ بهتری از خودت بساز.</p><button class="hero-link" data-tab="plan">مرور پلن معاملاتی ${icon('arrow')}</button></div></section><section class="card time-card"><div class="section-head"><h2>${icon('clock')} نبض زمان</h2><span class="tag" id="active-session"></span></div><div class="clock-row"><span>نیویورک <small>UTC−4 ثابت</small></span><strong id="ny-clock" dir="ltr"></strong></div><div class="clock-row"><span>تهران <small>UTC+3:30</small></span><strong id="tehran-clock" dir="ltr"></strong></div><div class="date-line"><span id="persian-date"></span><span id="gregorian-date" dir="ltr"></span></div></section></div><section class="card market-section">${sectionHeader('Market watch',`<div class="market-tools"><span class="muted">داده‌های آنلاین بازار</span>${btn('refresh-market','به‌روزرسانی','text-button')}</div>`)}<div class="market-columns"><div><h3>TradingView</h3><iframe id="market-frame" title="Market watch" src="${h(marketWidgetURL(state.settings.theme))}" sandbox="allow-scripts allow-same-origin allow-popups allow-popups-to-escape-sandbox" referrerpolicy="no-referrer" class="market-frame"></iframe><p class="micro">TradingView · نمایش آنلاین با تأخیر احتمالی</p>${btn('watch-symbols','افزودن / حذف نماد','small-button')}</div><div class="public-market"><h3>بازار داخلی</h3>${publicMarketCard('دلار آزاد','usd')}${publicMarketCard('یک گرم طلای ۱۸ عیار','gold18')}${publicMarketCard('سکه تمام بهار آزادی','coin')}${publicMarketCard('نیم‌سکه','halfCoin')}${publicMarketCard('ربع‌سکه','quarterCoin')}<p class="micro">Iran Market / TGJU · <span id="market-status">${marketBusy?'در حال دریافت…':h(marketError)}</span></p><small class="muted">${state.publicMarket.updatedAt?'آخرین به‌روزرسانی: '+h(new Date(state.publicMarket.updatedAt).toLocaleString('fa-IR')):'برای دریافت، دکمهٔ به‌روزرسانی را بزنید.'}</small></div></div></section><section class="card economic-calendar">${sectionHeader('تقویم اقتصادی',`<span class="tag">قرمز سپس نارنجی</span>`)}<div id="calendar-content">${calendarMarkup()}</div></section><div class="dashboard-grid"><section class="card performance">${sectionHeader('مسیر عملکرد شما','<span class="muted">سود و زیان تجمعی · USD</span>')}${performanceChart()}<div class="chart-caption"><span><i class="legend-dot"></i> نتیجهٔ معاملات ثبت‌شده</span><button data-tab="money" class="text-button">گزارش کامل ${icon('arrow')}</button></div></section><section class="card">${sectionHeader('آخرین معاملات',`<button data-tab="journal" class="text-button">مشاهده همه ${icon('arrow')}</button>`)}${tradeTable([...state.trades].sort(sortTrades).slice(0,5),false)}</section></div>`;}
function publicMarketCard(label,key){const value=state.publicMarket[key];return `<div class="public-quote"><span>${label}<small>ریال</small></span><div><strong>${value?n(value.price):'—'}</strong><small>${value?h(new Date(value.at).toLocaleString('fa-IR'))+(value.stale?' · قدیمی':''):'داده در دسترس نیست'}</small></div></div>`;}
function calendarMarkup(){const today=dayKey(),items=calendarDay===today?calendarItems:[],time=(date,zone)=>new Intl.DateTimeFormat('fa-IR',{timeZone:zone,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(date));return `<p class="micro">Forex Factory · روز ایران: ${today} / ${persianDate(today)} · ساعت نیویورک با تغییر ساعت فصلی</p>${btn('refresh-calendar',calendarBusy?'در حال دریافت…':'دریافت تقویم اقتصادی','text-button',calendarBusy?'disabled':'')}<p role="status">${h(calendarError)}</p>${items.length?`<div class="calendar-list">${items.map(item=>`<article class="calendar-item"><span class="impact ${item.impact==='High'?'red':'orange'}">${item.impact==='High'?'مهم':'متوسط'}</span><strong>${h(item.title)} <bdi>${h(item.country)}</bdi></strong><span>ایران ${time(item.date,'Asia/Tehran')}<br>نیویورک ${time(item.date,'America/New_York')}</span></article>`).join('')}</div>`:`<p class="muted">${calendarDay===today?'خبر قرمز یا نارنجی برای امروز در پاسخ منبع نیست.':'اخبار امروز دریافت نشده است.'}</p>`}`;}
async function refreshMarket(){if(marketBusy)return;marketBusy=true;marketError='';updateOnlinePanels();try{const data=await fetchPublicMarket();await commit(s=>s.publicMarket=data);}catch(e){marketError='دریافت قیمت‌ها ناموفق بود؛ دادهٔ قبلی با زمان آن حفظ شد.';}finally{marketBusy=false;updateOnlinePanels();}}
async function refreshCalendar(){if(calendarBusy)return;calendarBusy=true;calendarError='';updateOnlinePanels();const requestedDay=dayKey();try{calendarItems=await fetchEconomicCalendar();calendarDay=requestedDay;}catch(e){calendarError='اتصال به تقویم اقتصادی ممکن نیست؛ دوباره تلاش کنید.';}finally{calendarBusy=false;updateOnlinePanels();}}
function updateOnlinePanels(){const el=document.getElementById('calendar-content');if(el)el.innerHTML=calendarMarkup();const status=document.getElementById('market-status');if(status)status.textContent=marketBusy?'در حال دریافت…':marketError;}
function watchSymbols(){openDialog('نمادهای TradingView',`<form id="watch-add" class="inline-actions">${field('شناسهٔ منبع و نماد','symbol','','text','required placeholder="NASDAQ:AAPL" maxlength="60" dir="ltr"')}<button class="button">افزودن</button></form>${state.watchSymbols.map(symbol=>`<div class="section-head"><bdi>${h(symbol)}</bdi>${btn('remove-watch','حذف','small-button',`data-symbol="${h(symbol)}"`)}</div>`).join('')}`);}
function statCard(label,value,symbol,color,sub,cls=''){return `<article class="card stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}">${icon(symbol)}</span></div><strong class="stat-value ${cls}">${value}</strong><small>${sub}</small></article>`;}
function performanceChart(){const trades=[...state.trades].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));if(!trades.length)return `<div class="chart-empty"><div class="chart-grid-lines"></div><div><span class="empty-chart-icon">${icon('technical')}</span><strong>داستان عملکردت از اولین معامله شروع می‌شود</strong><p>با ثبت معاملات، مسیر سود و زیان اینجا شکل می‌گیرد.</p>${btn('new-trade','ثبت اولین معامله','text-button')}</div></div>`;let sum=0;const values=[0,...trades.map(t=>sum+=t.pnl)],min=Math.min(...values),max=Math.max(...values),range=max-min||1;const points=values.map((v,i)=>`${40+i/(values.length-1)*600},${180-(v-min)/range*150}`).join(' ');return `<div class="chart-wrap"><svg viewBox="0 0 680 220" role="img" aria-label="نمودار سود و زیان تجمعی به دلار"><defs><linearGradient id="fill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#93b7a5" stop-opacity=".3"/><stop offset="1" stop-color="#93b7a5" stop-opacity="0"/></linearGradient></defs>${[30,80,130,180].map(y=>`<path d="M40 ${y}H640" stroke="#e8ece7" stroke-dasharray="4 5"/>`).join('')}<polygon points="40,190 ${points} 640,190" fill="url(#fill)"/><polyline points="${points}" fill="none" stroke="#4a806b" stroke-width="3"/><text x="40" y="212" font-size="12" fill="#78867f">${h(trades[0].date)}</text><text x="540" y="212" font-size="12" fill="#78867f">${h(trades[trades.length-1].date)}</text><text x="45" y="22" font-size="12" fill="#78867f">max $${max.toFixed(2)} / min $${min.toFixed(2)}</text></svg></div>`;}
const sortTrades=(a,b)=>(b.date+b.time).localeCompare(a.date+a.time);
function tradeTable(trades,actions=true){if(!trades.length)return empty('هنوز معامله‌ای در این بازه ثبت نشده است.','new-trade','ثبت معامله');return `<div class="table-scroll"><table><thead><tr><th>نماد / حساب</th><th>تاریخ و ساعت نیویورک</th><th>نتیجه</th><th>سود / زیان</th>${actions?'<th>جزئیات</th>':''}</tr></thead><tbody>${[...trades].sort(sortTrades).map(t=>`<tr><td><strong dir="ltr">${h(t.symbol)}</strong><small>${h(accountName(t.account))}</small></td><td><bdi>${h(t.date)} · ${h(t.time)}</bdi><small>${persianDate(t.date)}</small></td><td><span class="result ${t.result==='TP'?'win':'loss'}">${t.result}</span></td><td class="${t.pnl>=0?'positive':'negative'}">${money(t.pnl)}</td>${actions?`<td>${btn('edit-trade',icon('edit'),'icon-button',`data-id="${h(t.id)}" aria-label="جزئیات و ویرایش معامله"`)}${btn('delete',icon('trash'),'icon-button',`data-kind="trades" data-id="${h(t.id)}" aria-label="حذف معامله"`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function page(){const titles={money:['مدیریت مالی','موجودی، سود و زیان و قوانین روزانه.'],education:['آموزش','سه مسیر برای ساختن مهارت معامله‌گری.'],plan:['پلن معاملاتی','قبل از بازار، مسیر تصمیم‌هایت را مشخص کن.'],checklists:['چک‌لیست','تحلیل چندتایم‌فریمی EUR/GBP را ثبت و مقایسه کن.'],journal:['ژورنال‌نویسی','معاملاتت را ثبت کن؛ الگوهایت را بشناس.'],accounts:['حساب‌های معاملاتی','نمای یکپارچه‌ای از سرمایه و عملکرد تو.']};const [title,subtitle]=titles[tab];return heading(title,subtitle,tab==='accounts'?btn('new-account',icon('plus')+' حساب جدید','button primary'):tab==='journal'?btn('new-trade',icon('plus')+' ثبت معامله','button primary'):'')+(tab==='accounts'?accountsPage():tab==='journal'?journalPage()+notes():tab==='money'?moneyPage():tab==='education'?educationPage():tab==='plan'?planPage():tab==='checklists'?checklistPage():journalPage());}
function notes(){return `<section class="card">${sectionHeader('یادداشت‌های ژورنال',btn('new-note','یادداشت جدید','button secondary'))}${state.notes.filter(x=>x.section==='journal').sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<article class="education-note"><small>${h(x.date)} · ${persianDate(x.date)}</small><p>${h(x.text)}</p>${btn('edit-note','ویرایش','small-button',`data-id="${h(x.id)}"`)}${btn('delete','حذف','small-button',`data-kind="notes" data-id="${h(x.id)}"`)}</article>`).join('')}</section>`;}
function inputHints(){document.querySelectorAll('input[type="date"],input[data-usd]').forEach(input=>{let hint=input.nextElementSibling;if(!hint?.classList.contains('input-hint')){hint=document.createElement('small');hint.className='input-hint';hint.setAttribute('aria-live','polite');input.after(hint);}hint.textContent=!input.value?'':input.type==='date'?(Number.isFinite(Date.parse(input.value))?persianDate(input.value):''):rialHint(input.value);});}
document.addEventListener('input',inputHints);
function educationPage(){const groups=[['technical','تحلیل تکنیکال','ساختار بازار، روند و ستاپ‌ها'],['money','مدیریت سرمایه','ریسک، اندازه پوزیشن و بازده'],['mind','مدیریت روانی','انضباط، تمرکز و کنترل هیجان']];return `<section class="education-shell">${groups.map(([category,title,sub])=>{const items=state.educationNotes.filter(x=>x.category===category).sort((a,b)=>Number(b.pinned)-Number(a.pinned)||b.createdAt.localeCompare(a.createdAt)||b.id.localeCompare(a.id));return `<section class="education-panel education-${category}"><div class="section-head"><div><span class="eyebrow">LEARNING PATH</span><h2>${title}</h2><p class="muted">${sub}</p></div>${btn('new-education-note','افزودن نوت','button secondary',`data-category="${category}"`)}</div>${items.length?items.map(x=>`<article class="education-note ${x.pinned?'pinned':''}"><div><strong>${h(x.title)}</strong><small>${persianDate(x.date)} · ${x.pinned?'پین‌شده':''}</small></div><p>${h(x.text)}</p><div>${btn('pin-education',x.pinned?'برداشتن پین':'پین کردن','small-button',`data-id="${h(x.id)}"`)}${btn('edit-education','ویرایش','small-button',`data-id="${h(x.id)}"`)}${btn('delete','حذف','small-button',`data-kind="educationNotes" data-id="${h(x.id)}"`)}</div></article>`).join(''):empty('هنوز نوتی ثبت نشده است.')}</section>`;}).join('')}</section>`;}
function accountsPage(){return `<section class="card">${sectionHeader('حساب‌ها',exportButtons('accounts'))}${state.accounts.length?`<div class="accounts-grid">${state.accounts.map(a=>{const st=accountStats(a,state.trades);return `<article class="account-card"><div class="section-head"><span class="stat-icon sage">${icon('accounts')}</span><span class="tag">${h(a.type)}</span></div><h2>${h(a.name)}</h2><p class="muted">${h(a.broker)} · ${persianDate(a.date)}</p><div class="account-balance">${money(st.balance)}</div><div class="account-detail"><span>سپرده اولیه</span><strong>${money(a.deposit)}</strong></div><div class="account-detail"><span>سود / زیان</span><strong class="${st.pnl>=0?'positive':'negative'}">${money(st.pnl)}</strong></div>${a.type==='پراپ'&&a.profitShare!==undefined?`<div class="account-detail"><span>سهم سود من (${n(a.profitShare)}٪)</span><strong>${money(st.profitShare)}</strong></div>`:''}<div class="account-detail"><span>بازده معاملات</span><strong>${n(st.percent)}٪</strong></div>${btn('select-account','نمودار سرمایه','button secondary',`data-id="${h(a.id)}" aria-expanded="${selectedAccount===a.id}"`)}${selectedAccount===a.id?accountChart(a,state.trades):''}<div class="inline-actions">${btn('edit-account','ویرایش','small-button',`data-id="${h(a.id)}"`)}${btn('delete','حذف','small-button',`data-kind="accounts" data-id="${h(a.id)}"`)}</div></article>`;}).join('')}</div>`:empty('برای شروع، حساب واقعی، دمو یا پراپ خود را اضافه کنید.','new-account','افزودن حساب')}</section>`;}
function accountChart(account,trades){const rows=trades.filter(t=>t.account===account.id).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));let balance=account.deposit;const data=[{time:Date.parse(account.date+'T00:00:00-04:00'),value:balance},...rows.map(t=>({time:Date.parse(t.date+'T'+t.time+':00-04:00'),value:balance+=t.pnl}))].sort((a,b)=>a.time-b.time);const min=Math.min(...data.map(x=>x.value)),max=Math.max(...data.map(x=>x.value)),range=max-min||1,start=data[0].time,end=data.at(-1).time,points=data.map(x=>`${80+(x.time-start)/(end-start||1)*490},${180-(x.value-min)/range*140}`).join(' ');return `<div class="account-chart"><svg viewBox="0 0 640 230" role="img" aria-label="سرمایه حساب بر حسب زمان به دلار"><path d="M80 30V180H590"/><polyline points="${points}"/>${data.map(x=>`<circle cx="${80+(x.time-start)/(end-start||1)*490}" cy="${180-(x.value-min)/range*140}" r="4"><title>${new Date(x.time).toISOString().slice(0,10)}: $${x.value}</title></circle>`).join('')}<text x="8" y="45">$${max.toFixed(2)}</text><text x="8" y="180">$${min.toFixed(2)}</text><text x="80" y="210">${new Date(start).toISOString().slice(0,10)}</text><text x="480" y="210">${new Date(end).toISOString().slice(0,10)}</text></svg><small>محور افقی: زمان · محور عمودی: سرمایه (USD)</small></div>`;}
function filterPanel(){return `<form id="filters" class="filter-panel"><label>حساب<select name="account"><option value="">همه حساب‌ها</option>${state.accounts.map(a=>`<option value="${h(a.id)}" ${filters.account===a.id?'selected':''}>${h(a.name)}</option>`).join('')}</select></label><label>از تاریخ میلادی<input type="date" required name="start" value="${filters.start}"></label><label>تا تاریخ میلادی<input type="date" required name="end" value="${filters.end}"></label><button class="button secondary" type="submit">اعمال بازه</button><div class="inline-actions">${btn('range','۷ روز اخیر','small-button','data-range="week"')}${btn('range','ماه جاری','small-button','data-range="month"')}</div></form>`;}
function reportStats(){const st=statistics(filterTrades(state.trades,filters));return `<div class="report-stats"><div><small>تعداد معاملات</small><strong>${n(st.count)}</strong></div><div><small>موفق / ناموفق</small><strong><span class="positive">${n(st.wins)}</span> / <span class="negative">${n(st.losses)}</span></strong></div><div><small>نرخ موفقیت</small><strong>${n(st.winRate)}٪</strong></div><div><small>سود و زیان</small><strong class="${st.pnl>=0?'positive':'negative'}">${money(st.pnl)}</strong></div></div>`;}
function journalPage(){return `<section class="card">${sectionHeader('معاملات و گزارش بازه',`<div class="inline-actions">${btn('symbols','مدیریت نمادها','small-button')}${exportButtons('trades')}</div>`)}${filterPanel()}${reportStats()}${tradeTable(filterTrades(state.trades,filters))}</section>`;}
function moneyPage(){const stats=statistics(state.trades);return `<section class="card">${sectionHeader('خلاصه مدیریت مالی',exportButtons('trades'))}<div class="stats-grid">${statCard('موجودی کل حساب‌ها',money(state.accounts.reduce((sum,a)=>sum+accountStats(a,state.trades).balance,0)),'accounts','sage','تمام حساب‌ها')}${statCard('سود و زیان خالص',money(stats.pnl),'technical','blue','تمام معاملات',stats.pnl<0?'negative':'positive')}${statCard('نرخ موفقیت معاملات',`${n(stats.winRate)}<small>٪</small>`,'check','sand',`${n(stats.wins)} موفق از ${n(stats.count)} معامله`)}</div>${filterPanel()}${reportStats()}</section><section class="card rules-card">${sectionHeader('قوانین',btn('new-rule','افزودن قانون','button secondary'))}<p class="muted">قوانین روز معامله را تعریف کنید و پیش از ورود بررسی کنید.</p>${state.rules.map(rule=>`<div class="check-row"><label><input type="checkbox" data-rule="${h(rule.id)}" ${rule.done&&state.rulesDate===dayKey()?'checked':''}><span>${h(rule.text)}</span></label>${btn('edit-rule','ویرایش','icon-button',`data-id="${h(rule.id)}"`)}${btn('delete','حذف','small-button',`data-kind="rules" data-id="${h(rule.id)}"`)}</div>`).join('')}</section><section class="card">${sectionHeader('هزینه‌ها',`<div class="inline-actions">${exportButtons('costs')}${btn('new-cost',icon('plus')+' هزینه جدید','small-button')}</div>`)}<div class="cost-total"><span>مجموع هزینه‌ها</span><strong>${money(state.costs.reduce((sum,c)=>sum+c.amount,0))}</strong></div>${state.costs.length?`<div class="table-scroll"><table><thead><tr><th>عنوان</th><th>تاریخ</th><th>هزینه</th><th>عملیات</th></tr></thead><tbody>${state.costs.map(c=>`<tr><td>${h(c.title)}</td><td>${h(c.date)}<small>${persianDate(c.date)}</small></td><td>${money(c.amount)}</td><td>${btn('edit-cost',icon('edit'),'icon-button',`data-id="${h(c.id)}" aria-label="ویرایش هزینه"`)}${btn('delete',icon('trash'),'icon-button',`data-kind="costs" data-id="${h(c.id)}" aria-label="حذف هزینه"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('هزینه‌ای ثبت نشده است.')}</section>`;}
function checklistField(value,attrs=''){return `<input class="checklist-input" value="${h(value)}" ${attrs}>`;}
function checklistTable(doc,tf){return `<article class="checklist-tf tf-${tf.id}"><div class="checklist-tf-head"><div><span class="tf-kicker">TIME FRAME</span><h3>${h(tf.label)}</h3></div><label class="tf-date">تاریخ بررسی<input type="date" value="${h(tf.date)}" data-cl-date="${h(tf.id)}"></label></div><div class="checklist-scroll"><table class="checklist-table"><thead><tr><th>بخش</th><th>معیار</th>${['GBP','EUR','DXY'].map(s=>`<th colspan="3"><label class="symbol-check"><input type="checkbox" ${tf.rows.every(r=>r.checks[s])?'checked':''} data-cl-check="${h(tf.id)}:${s}"><bdi>${s}</bdi></label><small>سه به‌روزرسانی</small></th>`).join('')}</tr><tr><th></th><th></th>${['GBP','EUR','DXY'].map(()=>'<th>۱</th><th>۲</th><th>۳</th>').join('')}</tr></thead><tbody>${tf.rows.map((row,ri)=>`<tr><td>${h(row.group)}</td><td>${h(row.label)}</td>${['GBP','EUR','DXY'].map(symbol=>row.values[symbol].map((value,ci)=>`<td>${checklistField(value,`data-cl-value="${h(tf.id)}:${ri}:${symbol}:${ci}" aria-label="${h(tf.label)} ${symbol} ${row.label} به‌روزرسانی ${ci+1}"`)}</td>`).join('')).join('')}</tr>`).join('')}</tbody></table></div><label class="context-field">Context<textarea rows="3" data-cl-context="${h(tf.id)}">${h(tf.context)}</textarea></label></article>`;}
function checklistSummary(doc){const list=doc.timeframes;return `<section class="card checklist-compare"><div class="section-head"><div><span class="eyebrow">MULTI-TIMEFRAME VIEW</span><h2>مقایسهٔ سه تایم‌فریم</h2></div><span class="tag">خلاصهٔ کنار هم</span></div><div class="compare-controls">${[0,1,2].map(i=>`<label>قاب ${i+1}<select data-cl-compare="${i}">${list.map(tf=>`<option value="${h(tf.id)}" ${checklistCompare[i]===tf.id?'selected':''}>${h(tf.label)}</option>`).join('')}</select></label>`).join('')}</div><div class="compare-grid">${checklistCompare.map(id=>{const tf=list.find(x=>x.id===id)||list[0];const done=tf.rows.reduce((n,row)=>n+['GBP','EUR','DXY'].filter(s=>row.checks[s]).length,0);return `<article class="compare-card tf-${tf.id}"><span>${h(tf.label)}</span><strong>${n(done)}</strong><small>تأیید از ${n(tf.rows.length*3)}</small><p>${h(tf.context||'بدون Context')}</p></article>`;}).join('')}</div></section>`;}
function checklistPage(){const doc=state.checklists.find(d=>d.id===state.checklistSelected)||state.checklists[0];return `${heading('چک‌لیست','ثبت ساختاریافتهٔ تحلیل EUR/GBP در چند تایم‌فریم.',`<div class="inline-actions">${btn('export-checklist','خروجی Word','button secondary')}${btn('new-checklist','چک‌لیست جدید','small-button')}</div>`)}<section class="card checklist-picker"><label>انتخاب چک‌لیست<select data-cl-select>${state.checklists.map(d=>`<option value="${h(d.id)}" ${d.id===doc.id?'selected':''}>${h(d.title)}</option>`).join('')}</select></label><p class="micro">ابتدا یک چک‌لیست را انتخاب کنید؛ اطلاعات هر تایم‌فریم مستقل ذخیره می‌شود.</p></section>${checklistSummary(doc)}<section class="checklist-stack">${doc.timeframes.map(tf=>checklistTable(doc,tf)).join('')}</section><section class="card lower-tf"><div class="section-head"><div><span class="eyebrow">EXECUTION</span><h2>تایم‌فریم‌های زیر H1</h2></div><span class="tag">ورود و تریگر</span></div><label>نماد مورد معامله<input dir="ltr" value="${h(doc.lower.symbol)}" data-cl-lower="symbol" placeholder="EURGBP"></label><div class="lower-grid">${[['of','1. OF'],['huntShift','2. Hunt-Shift'],['stm','3. STM'],['trigger15sec','4. Trigger 15sec']].map(([key,label])=>`<label class="check-row"><input type="checkbox" ${doc.lower[key]?'checked':''} data-cl-lower="${key}"><span>${label}</span></label>`).join('')}</div></section>`;}
function planPage(){return `<section class="card">${sectionHeader('مسیر تصمیم‌گیری',`<div class="inline-actions">${exportButtons('steps')}${btn('new-step',icon('plus')+' مرحله جدید','button secondary')}</div>`)}<p class="muted">مراحل ورود تا خروج را به ترتیب تعریف کنید؛ هر مرحله قابل ویرایش و جابه‌جایی است.</p>${state.steps.length?`<div class="flow">${state.steps.map((step,i)=>`<div class="flow-unit"><article class="flow-step"><span class="step-num">${n(i+1)}</span><div><h3>${h(step.text)}</h3><p class="step-description">${h(step.description)}</p></div><div>${btn('edit-step',icon('edit'),'icon-button',`data-id="${h(step.id)}" aria-label="ویرایش مرحله"`)}${btn('move-step','↑','icon-button',`data-id="${h(step.id)}" ${i===0?'disabled':''} aria-label="انتقال به مرحله قبل"`)}${btn('delete',icon('trash'),'icon-button',`data-kind="steps" data-id="${h(step.id)}" aria-label="حذف مرحله"`)}</div></article>${i<state.steps.length-1?'<span class="flow-arrow" aria-hidden="true">↓</span>':''}</div>`).join('')}</div>`:empty('پلن شما، نقشهٔ راه شماست. اولین مرحله را تعریف کنید.','new-step','تعریف اولین مرحله')}</section>`;}
function updateClock(){const now=new Date();for(const [id,value] of Object.entries({'ny-clock':clockAt(now,-4),'tehran-clock':clockAt(now,3.5),'active-session':sessionAt(now)==='None'?'بدون سشن فعال':`سشن ${sessionAt(now)}`,'persian-date':persianDate(dayKey(now)),'gregorian-date':dayKey(now)})){const el=document.getElementById(id);if(el)el.textContent=value;}if(state?.rulesDate!==dayKey())document.querySelectorAll('[data-rule]').forEach(el=>el.checked=false);if(calendarDay&&calendarDay!==dayKey()&&!calendarBusy)updateOnlinePanels();if(state?.checklistDate&&state.checklistDate!==dayKey())document.querySelectorAll('[data-check]').forEach(el=>el.checked=false);}
function field(label,name,value='',type='text',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${h(value)}" ${attrs} ${label.includes('USD')?'data-usd':''}></label>`;}
function textarea(label,name,value='',attrs=''){return `<label class="full">${label}<textarea name="${name}" rows="5" ${attrs}>${h(value)}</textarea></label>`;}
function openDialog(title,content,form='',id=''){modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2>${btn('close',icon('close'),'icon-button','aria-label="بستن"')}</div>${form?`<form id="editor" data-form="${form}" data-id="${h(id)}" class="form-grid">${content}<p class="form-error full" role="alert"></p><div class="modal-actions full"><button type="submit" class="button primary">ذخیره</button>${btn('close','انصراف','button')}</div></form>`:content}`;inputHints();if(!modal.open)modal.showModal();}
function editor(kind,id){const account=state.accounts.find(a=>a.id===id),trade=state.trades.find(t=>t.id===id),note=state.notes.find(t=>t.id===id),cost=state.costs.find(t=>t.id===id),step=state.steps.find(t=>t.id===id);if(kind==='account'){const a=account||{name:'',type:'دمو',broker:'',deposit:'',date:dayKey()};openDialog(account?'ویرایش حساب':'حساب معاملاتی جدید',field('نام حساب','name',a.name,'text','required maxlength="200"')+`<label>نوع حساب<select name="type">${['واقعی','دمو','پراپ'].map(v=>`<option ${a.type===v?'selected':''}>${v}</option>`).join('')}</select></label>`+field('سپرده اولیه (USD)','deposit',a.deposit,'number','min="0" max="1000000000000" step="any" required')+field('سهم شما از سود پراپ (درصد، اختیاری)','profitShare',a.profitShare??'','number','min="0" max="100" step="any"')+field('بروکر','broker',a.broker,'text','required maxlength="200"')+field('تاریخ ایجاد (میلادی)','date',a.date,'date','required'),'account',id);}
if(kind==='trade'){if(!state.accounts.length){toast('ابتدا یک حساب معاملاتی بسازید.');editor('account');return;}const t=trade||{account:state.accounts[0].id,date:dayKey(),symbol:state.symbols[0]||'',time:clockAt(new Date(),-4).slice(0,5),result:'TP',pnl:'',note:'',image:''};openDialog(trade?'جزئیات و ویرایش معامله':'ثبت معامله جدید',`<label>حساب<select name="account" required>${state.accounts.map(a=>`<option value="${h(a.id)}" ${a.id===t.account?'selected':''}>${h(a.name)}</option>`).join('')}</select></label>`+field('تاریخ معامله (میلادی)','date',t.date,'date','required')+`<label>نماد؛ انتخاب یا تایپ نماد جدید<input name="symbol" list="symbol-list" value="${h(t.symbol)}" required maxlength="30" dir="ltr"><datalist id="symbol-list">${state.symbols.map(s=>`<option value="${h(s)}"></option>`).join('')}</datalist></label>`+field('ساعت نیویورک (UTC−4 ثابت)','time',t.time,'time','required')+`<label>نتیجه<select name="result"><option value="TP" ${t.result==='TP'?'selected':''}>TP — موفق</option><option value="SL" ${t.result==='SL'?'selected':''}>SL — ناموفق</option></select></label>`+field('مقدار سود یا زیان، بدون علامت (USD)','amount',t.pnl===''?'':Math.abs(t.pnl),'number','min="0" max="1000000000000" step="any" required')+textarea('توضیحات معامله','note',t.note,'maxlength="10000"')+`<label class="full">تصویر معامله (PNG، JPEG یا WebP، حداکثر ۲ مگابایت)<input name="image" type="file" accept="image/png,image/jpeg,image/webp"></label>${t.image?`<div class="full"><img class="attachment-preview" src="${h(t.image)}" alt="تصویر معامله"><label class="check-row"><input type="checkbox" name="removeImage">حذف تصویر فعلی</label></div>`:''}`,'trade',id);}
if(kind==='note')openDialog(note?'ویرایش یادداشت':'اصول، قواعد و یادگیری',field('تاریخ یادداشت','date',note?.date||dayKey(),'date','required')+textarea('متن یادداشت','text',note?.text||'','required maxlength="10000"'),'note',id);
if(kind==='cost')openDialog(cost?'ویرایش هزینه':'ثبت هزینه',field('عنوان هزینه','title',cost?.title||'','text','required maxlength="200"')+field('مبلغ (USD)','amount',cost?.amount??'','number','required min="0" max="1000000000000" step="any"')+field('تاریخ','date',cost?.date||dayKey(),'date','required'),'cost',id);
if(kind==='education'){const item=state.educationNotes.find(x=>x.id===id);educationCategory=item?.category||educationCategory;openDialog(item?'ویرایش نوت':'نوت آموزشی جدید',field('عنوان','title',item?.title||'','text','required maxlength="200"')+field('تاریخ','date',item?.date||dayKey(),'date','required')+textarea('متن نوت','text',item?.text||'','required maxlength="10000"'),'education',id);}
if(kind==='rule'){const item=state.rules.find(x=>x.id===id);openDialog(item?'ویرایش قانون':'قانون جدید',textarea('متن قانون','text',item?.text||'','required maxlength="500"'),'rule',id);}
if(kind==='step')openDialog(step?'ویرایش مرحله':'مرحله جدید در پلن',textarea('عنوان مرحله','text',step?.text||'','required maxlength="500"')+textarea('توضیحات مرحله','description',step?.description||'','maxlength="5000"'),'step',id);
}
function settings(){openDialog('تنظیمات و نگهداری اطلاعات',`<form id="settings-form" class="form-grid"><label class="check-row full"><input type="checkbox" name="autoRate" ${state.settings.autoRate!==false?'checked':''}>دریافت خودکار نرخ دلار از وب، هر ۵ دقیقه</label>${field('نرخ دستی تومان (فقط با خاموش‌کردن حالت خودکار)','rate',state.settings.rate||'','number','min="0" max="1000000000000" step="any"')}<p class="micro">${rateStatus()}<br>منبع عمومی: Iran Market با دادهٔ TGJU؛ قیمت بازار آزاد از ابتدا به تومان است و دوباره بر ۱۰ تقسیم نمی‌شود. انتشار منبع معمولاً هر ۳۰ دقیقه است. در خطا، نرخ قبلی حفظ و زمان آن نمایش داده می‌شود.</p>${field('مسیر API نرخ‌ها روی همین دامنه (اختیاری)','feed',state.settings.feed,'text','placeholder="./api/quotes" maxlength="500"')}<p class="micro">اتصال زنده به سرویس ارائه‌دهنده نیاز دارد. ساختار پاسخ در راهنما آمده است؛ کلید محرمانه را اینجا وارد نکنید.</p><button class="button primary">ذخیره تنظیمات</button></form><hr><h3>نسخهٔ پشتیبان</h3><p class="muted">اطلاعات در همین مرورگر نگهداری می‌شود؛ همگام‌سازی ابری ندارد. قبل از پاک‌کردن مرورگر پشتیبان بگیرید. فایل پشتیبان شامل تصویر معاملات و رمزگذاری‌نشده است.</p><div class="inline-actions">${btn('backup',icon('download')+' دریافت پشتیبان','button secondary')}<label class="button">بازیابی پشتیبان<input id="import-backup" type="file" accept=".json,application/json" hidden></label></div><p class="micro">بازیابی پس از تأیید، تمام اطلاعات فعلی را جایگزین می‌کند.</p><hr><p class="muted">نصب در Safari آیفون: Share ← Add to Home Screen. در دسکتاپ از گزینهٔ نصب مرورگر استفاده کنید. نصب و آفلاین به HTTPS نیاز دارد.</p><a href="./guide.html" target="_blank" rel="noopener" class="text-button">راهنمای کامل</a>`);}
function symbols(){openDialog('مدیریت نمادها',`<p class="muted">ویرایش نماد، معاملات قبلی آن را هم به‌روز می‌کند. نماد دارای معامله قابل حذف نیست.</p><form id="symbol-add" class="inline-actions"><input name="symbol" aria-label="نماد جدید" placeholder="BTCUSD" maxlength="30" required dir="ltr"><button class="button secondary">افزودن</button></form><div class="symbol-list">${state.symbols.map(s=>`<div><bdi>${h(s)}</bdi><span>${btn('rename-symbol','ویرایش','small-button',`data-symbol="${h(s)}"`)}${btn('delete-symbol','حذف','small-button',`data-symbol="${h(s)}"`)}</span></div>`).join('')}</div>`);}
async function imageData(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024)throw Error('یک تصویر PNG، JPEG یا WebP تا ۲ مگابایت انتخاب کنید.');const bytes=new Uint8Array(await file.slice(0,12).arrayBuffer());const signature=file.type==='image/png'?bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71:file.type==='image/jpeg'?bytes[0]===255&&bytes[1]===216&&bytes[2]===255:String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!signature)throw Error('محتوای فایل با نوع تصویر مطابقت ندارد.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('تصویر قابل خواندن نیست.'));reader.readAsDataURL(file);});}
async function submitEditor(form){const values=Object.fromEntries(new FormData(form));const id=form.dataset.id||Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join(''),kind=form.dataset.form;let row,collection;if(kind==='account'){collection='accounts';row={id,name:values.name.trim(),type:values.type,deposit:Number(values.deposit),broker:values.broker.trim(),date:values.date};if(values.type==='پراپ'&&values.profitShare!==undefined&&values.profitShare!=='')row.profitShare=Number(values.profitShare);if(!row.name||!row.broker)throw Error('نام حساب و بروکر را وارد کنید.');}
if(kind==='trade'){collection='trades';let image=state.trades.find(t=>t.id===id)?.image||'';if(values.removeImage)image='';if(values.image?.size)image=await imageData(values.image);row={id,account:values.account,date:values.date,time:values.time,symbol:values.symbol.trim().toUpperCase(),result:values.result,pnl:Math.abs(Number(values.amount))*(values.result==='SL'?-1:1),note:values.note.trim(),image};}
if(kind==='note'){collection='notes';row={id,section:state.notes.find(n=>n.id===id)?.section||tab,date:values.date,text:values.text.trim()};}
if(kind==='education'){collection='educationNotes';const old=state.educationNotes.find(x=>x.id===id);row={id,category:old?.category||educationCategory,title:values.title.trim(),text:values.text.trim(),date:values.date,createdAt:old?.createdAt||new Date().toISOString(),pinned:old?.pinned||false};}
if(kind==='rule'){collection='rules';row={id,text:values.text.trim(),done:state.rules.find(x=>x.id===id)?.done||false};}
if(kind==='cost'){collection='costs';row={id,title:values.title.trim(),amount:Number(values.amount),date:values.date};}
if(kind==='step'){collection='steps';row={id,text:values.text.trim(),description:(values.description||'').trim()};}
if((row.text!==undefined&&!row.text)||(row.title!==undefined&&!row.title))throw Error('متن نمی‌تواند خالی باشد.');await commit(s=>{if(kind==='trade'&&!s.symbols.includes(row.symbol))s.symbols.push(row.symbol);const index=s[collection].findIndex(v=>v.id===id);if(index<0)s[collection].push(row);else s[collection][index]=row;});modal.close();toast('با موفقیت ذخیره شد.');}
function report(type,format){let headers,rows,title;const unit=currencyTitle();if(type==='trades'){const trades=filterTrades(state.trades,filters),st=statistics(trades);const shared=state.accounts.filter(a=>a.type==='پراپ'&&a.profitShare!==undefined&&(!filters.account||filters.account===a.id)).map(a=>`${a.name}: ${accountStats(a,trades).profitShare.toFixed(2)} USD (${a.profitShare}٪)`).join('؛ ');title=`${shared?'سهم سود شما: '+shared+' | ':''}معاملات ${filters.start} تا ${filters.end} | تعداد ${st.count} | TP ${st.wins} | SL ${st.losses} | موفقیت ${st.winRate.toFixed(1)}٪ | خالص ${plainMoney(st.pnl).toFixed(2)} ${unit}`;headers=['حساب','تاریخ','ساعت نیویورک UTC−4','نماد','نتیجه',`سود/زیان (${unit})`,'یادداشت','تصویر پیوست'];rows=[...trades].sort(sortTrades).map(t=>[accountName(t.account),t.date,t.time,t.symbol,t.result,plainMoney(t.pnl),t.note,t.image?'دارد؛ در فایل پشتیبان موجود است':'ندارد']);}if(type==='notes'){title='اصول، قواعد و یادگیری — '+SECTIONS.find(s=>s[0]===tab)[1];headers=['تاریخ میلادی','تاریخ شمسی','یادداشت'];rows=state.notes.filter(n=>n.section===tab).sort((a,b)=>b.date.localeCompare(a.date)).map(n=>[n.date,persianDate(n.date),n.text]);}if(type==='accounts'){title='گزارش حساب‌های معاملاتی';headers=['حساب','نوع','بروکر','تاریخ',`سپرده (${unit})`,`موجودی (${unit})`,'بازده (%)','درصد سهم سود','سهم سود شما (USD)'];rows=state.accounts.map(a=>{const st=accountStats(a,state.trades);return [a.name,a.type,a.broker,a.date,plainMoney(a.deposit),plainMoney(st.balance),st.percent,a.profitShare??'تعیین نشده',a.type==='پراپ'&&a.profitShare!==undefined?st.profitShare:'—'];});}if(type==='costs'){title='گزارش سرمایه‌گذاری و هزینه‌ها';headers=['تاریخ','عنوان',`هزینه (${unit})`];rows=state.costs.map(c=>[c.date,c.title,plainMoney(c.amount)]);rows.push(['','مجموع',state.costs.reduce((s,c)=>s+plainMoney(c.amount),0)]);}if(type==='steps'){title='پلن معاملاتی';headers=['مرحله','عنوان','توضیحات'];rows=state.steps.map((s,i)=>[i+1,s.text,s.description]);}if(state.settings.currency==='IRT'&&state.settings.rate)title+=` | نرخ تبدیل: ${state.settings.rate} تومان؛ ثبت ${state.settings.rateAt}`;if(!rows.length){toast('داده‌ای برای خروجی وجود ندارد.');return;}exportReport(format,title,headers,rows);if(format==='pdf')toast('در پنجرهٔ چاپ، گزینهٔ ذخیره به‌صورت PDF را انتخاب کنید.');}
async function refreshFeed(silent=false){if(feedBusy)return;if(!state.settings.feed){if(!silent){const frame=document.getElementById('market-frame');const theme=state.settings.theme==='dark'?'dark':'light';if(frame)frame.src=marketWidgetURL(theme,Date.now());toast(navigator.onLine?'نمایش آنلاین بازار دوباره بارگذاری شد.':'برای نرخ آنلاین به اینترنت وصل شوید.');}return;}feedBusy=true;const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),10000);try{const url=new URL(state.settings.feed,location.href);if(url.origin!==location.origin||url.username||url.password)throw Error('فقط مسیر API روی همین دامنه مجاز است.');const response=await fetch(url,{cache:'no-store',signal:controller.signal,credentials:'same-origin'});if(!response.ok)throw Error('منبع نرخ در دسترس نیست.');const data=validateFeed(await response.json());await commit(s=>{s.quotes=data.quotes;s.quotesAt=data.timestamp;if(data.rate&&s.settings.autoRate===false){s.settings.rate=data.rate;s.settings.rateAt=data.timestamp;s.settings.rateSource='custom';}});if(!silent)toast('دادهٔ منبع دریافت شد؛ زمان داده را بررسی کنید.');}catch(error){if(!silent)toast(error.message==='Failed to fetch'?'دریافت نرخ ناموفق بود؛ اتصال و منبع را بررسی کنید.':error.message);}finally{clearTimeout(timeout);feedBusy=false;}}
function exportChecklist(){const doc=state.checklists.find(d=>d.id===state.checklistSelected)||state.checklists[0],rows=[];for(const tf of doc.timeframes){rows.push([tf.label,'تاریخ',tf.date]);for(const row of tf.rows)rows.push([`${row.group} ${row.label}`,...['GBP','EUR','DXY'].flatMap(s=>row.values[s])]);rows.push(['Context',tf.context]);}rows.push(['زیر H1',doc.lower.symbol,doc.lower.of?'OF':'',doc.lower.huntShift?'Hunt-Shift':'',doc.lower.stm?'STM':'',doc.lower.trigger15sec?'Trigger 15sec':'']);exportReport('docx',doc.title,['تایم‌فریم / بخش','GBP ۱','GBP ۲','GBP ۳','EUR ۱','EUR ۲','EUR ۳','DXY ۱','DXY ۲','DXY ۳'],rows);toast('فایل Word چک‌لیست آماده شد.');}
async function action(el){const a=el.dataset.action,id=el.dataset.id;if(a==='select-account'){selectedAccount=id;render();return;}if(a==='watch-symbols'){watchSymbols();return;}if(a==='remove-watch'){await commit(s=>s.watchSymbols=s.watchSymbols.filter(x=>x!==el.dataset.symbol));watchSymbols();return;}if(a==='refresh-market'){await Promise.all([refreshMarket(),refreshFeed()]);return;}if(a==='refresh-calendar'){await refreshCalendar();return;}if(a==='new-education-note'||a==='edit-education'){educationCategory=el.dataset.category||'technical';editor('education',id);return;}if(a==='new-rule'||a==='edit-rule'){editor('rule',id);return;}if(a==='pin-education'){await commit(s=>{const item=s.educationNotes.find(x=>x.id===id);if(!item.pinned&&s.educationNotes.filter(x=>x.pinned).length>=10)throw Error('حداکثر ۱۰ نوت را می‌توانید پین کنید.');item.pinned=!item.pinned;});return;}if(a==='export-checklist'){exportChecklist();return;}if(a==='new-checklist'){toast('چک‌لیست EUR/GBP آماده است.');return;}if(a==='close')modal.close();else if(a==='settings')settings();else if(a==='new-trade'||a==='edit-trade')editor('trade',id);else if(a==='new-account'||a==='edit-account')editor('account',id);else if(a==='new-note'||a==='edit-note')editor('note',id);else if(a==='new-cost'||a==='edit-cost')editor('cost',id);else if(a==='new-step'||a==='edit-step')editor('step',id);else if(a==='symbols')symbols();else if(a==='theme'){await commit(s=>s.settings.theme=s.settings.theme==='dark'?'light':'dark');}else if(a==='refresh-rate')await refreshDollarRate(true);else if(a==='currency'){if(state.settings.currency==='USD'&&!state.settings.rate){toast('برای تبدیل، نرخ دلار به تومان را وارد کنید.');settings();return;}await commit(s=>s.settings.currency=s.settings.currency==='USD'?'IRT':'USD');}else if(a==='range'){filters={...filters,...dateRange(el.dataset.range)};render();}else if(a==='delete'){const kind=el.dataset.kind;if(!['accounts','trades','notes','steps','costs','educationNotes','rules'].includes(kind))return;if(kind==='accounts'&&state.trades.some(t=>t.account===id)){toast('حساب دارای معامله حذف نمی‌شود؛ ابتدا معاملات مرتبط را مدیریت کنید.');return;}if(confirm('این مورد حذف شود؟ این کار قابل بازگشت نیست.'))await commit(s=>s[kind]=s[kind].filter(v=>v.id!==id));}else if(a==='move-step'){await commit(s=>{const i=s.steps.findIndex(v=>v.id===id);if(i>0)[s.steps[i-1],s.steps[i]]=[s.steps[i],s.steps[i-1]];});}else if(a==='export')report(el.dataset.type,el.dataset.format);else if(a==='backup')download(JSON.stringify(state,null,2),`MET-backup-${dayKey()}.json`,'application/json');else if(a==='refresh')await refreshFeed();else if(a==='delete-symbol'){const symbol=el.dataset.symbol;if(state.trades.some(t=>t.symbol===symbol)){toast('این نماد معاملهٔ ثبت‌شده دارد و قابل حذف نیست.');return;}if(confirm(`نماد ${symbol} حذف شود؟`)){await commit(s=>s.symbols=s.symbols.filter(v=>v!==symbol));symbols();}}else if(a==='rename-symbol'){const old=el.dataset.symbol,value=prompt('نام جدید نماد',old);if(!value)return;const symbol=value.trim().toUpperCase();if(!/^[A-Z0-9._/-]{1,30}$/.test(symbol))throw Error('نماد معتبر نیست.');if(symbol!==old&&state.symbols.includes(symbol))throw Error('این نماد وجود دارد.');await commit(s=>{s.symbols=s.symbols.map(v=>v===old?symbol:v);s.trades.forEach(t=>{if(t.symbol===old)t.symbol=symbol;});});symbols();}}
document.addEventListener('click',event=>{const nav=event.target.closest('[data-tab]');if(nav){tab=nav.dataset.tab;location.hash=tab;render();document.getElementById('main').focus();return;}const el=event.target.closest('[data-action]');if(el){if(el.closest('form'))event.preventDefault();action(el).catch(e=>toast(e.message||'عملیات انجام نشد.'));}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,button=form.querySelector('[type="submit"],button:not([type])');if(button)button.disabled=true;try{if(form.id==='editor')await submitEditor(form);if(form.id==='filters'){const data=Object.fromEntries(new FormData(form));if(data.start>data.end)throw Error('تاریخ شروع باید قبل از پایان باشد.');filters=data;render();}if(form.id==='settings-form'){const values=Object.fromEntries(new FormData(form)),feed=values.feed.trim();if(feed){const url=new URL(feed,location.href);if(url.origin!==location.origin||url.username||url.password||!['http:','https:'].includes(url.protocol))throw Error('منبع باید یک مسیر API روی همین دامنه باشد.');}await commit(s=>{s.settings.autoRate=values.autoRate==='on';const rate=Number(values.rate);if(!s.settings.autoRate&&(rate!==s.settings.rate||s.settings.rateSource!=='manual')){s.settings.rate=rate;s.settings.rateAt=new Date().toISOString();s.settings.rateSource='manual';}s.settings.feed=feed;if(!s.settings.rate)s.settings.currency='USD';});modal.close();rateError='';toast('تنظیمات ذخیره شد.');if(state.settings.autoRate)refreshDollarRate();}if(form.id==='watch-add'){const symbol=new FormData(form).get('symbol').trim().toUpperCase();if(!/^[A-Z0-9_]+:[A-Z0-9_.!/-]+$/.test(symbol)||state.watchSymbols.includes(symbol)||state.watchSymbols.length>=50)throw Error('شناسهٔ نماد نامعتبر، تکراری یا بیش از سقف ۵۰ نماد است.');await commit(s=>s.watchSymbols.push(symbol));watchSymbols();}if(form.id==='symbol-add'){const symbol=new FormData(form).get('symbol').trim().toUpperCase();if(!/^[A-Z0-9._/-]{1,30}$/.test(symbol))throw Error('نماد را با حروف لاتین، عدد، نقطه، خط تیره یا اسلش وارد کنید.');if(state.symbols.includes(symbol))throw Error('این نماد از قبل وجود دارد.');await commit(s=>s.symbols.push(symbol));symbols();}}catch(e){const err=form.querySelector('.form-error');if(err)err.textContent=e.message;else toast(e.message||'ذخیره نشد؛ فضای ذخیره‌سازی را بررسی کنید.');}finally{if(button)button.disabled=false;}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.dataset.rule){await commit(s=>{if(s.rulesDate!==dayKey())s.rules.forEach(x=>x.done=false);s.rulesDate=dayKey();s.rules.find(x=>x.id===el.dataset.rule).done=el.checked;});return;}if(el.dataset.clSelect!==undefined){await commit(s=>s.checklistSelected=el.value);return;}if(el.dataset.clCompare!==undefined){checklistCompare[Number(el.dataset.clCompare)]=el.value;render();return;}if(el.dataset.clValue||el.dataset.clContext||el.dataset.clDate||el.dataset.clLower||el.dataset.clCheck){await commit(s=>{const doc=s.checklists.find(d=>d.id===s.checklistSelected);if(!doc)return;if(el.dataset.clLower){if(el.dataset.clLower==='symbol')doc.lower.symbol=el.value;else doc.lower[el.dataset.clLower]=el.checked;return;}const tf=doc.timeframes.find(x=>x.id===(el.dataset.clDate||el.dataset.clContext||el.dataset.clValue?.split(':')[0]||el.dataset.clCheck?.split(':')[0]));if(!tf)return;if(el.dataset.clDate)tf.date=el.value;else if(el.dataset.clContext)tf.context=el.value;else if(el.dataset.clValue){const [,ri,symbol,ci]=el.dataset.clValue.split(':');tf.rows[Number(ri)].values[symbol][Number(ci)]=el.value;}else if(el.dataset.clCheck){const [,symbol]=el.dataset.clCheck.split(':');tf.rows.forEach(row=>row.checks[symbol]=el.checked);}});return;}if(el.dataset.check){const checked=el.checked;await commit(s=>{if(s.checklistDate!==dayKey())s.checklist.forEach(c=>c.done=false);s.checklistDate=dayKey();s.checklist.find(c=>c.id===el.dataset.check).done=checked;});}if(el.id==='import-backup'){const file=el.files[0];if(!file)return;if(file.size>50*1024*1024)throw Error('فایل پشتیبان باید کمتر از ۵۰ مگابایت باشد.');const incoming=validateState(JSON.parse(await file.text()));if(incoming.settings.feed){const url=new URL(incoming.settings.feed,location.href);if(url.origin!==location.origin||url.username||url.password)throw Error('مسیر منبع نرخ در پشتیبان مجاز نیست.');}if(!confirm('تمام اطلاعات فعلی با اطلاعات این فایل جایگزین شود؟ ابتدا از اطلاعات فعلی پشتیبان گرفته‌اید؟'))return;await commit(s=>Object.assign(s,incoming));modal.close();toast('پشتیبان با موفقیت بازیابی شد.');}}catch(e){toast(e.message||'بازیابی یا ذخیره انجام نشد.');if(el.dataset.check)render();}finally{if(el.id==='import-backup')el.value='';}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(SECTIONS.some(s=>s[0]===next)){tab=next;if(state)render();}});
for(const event of ['online','offline'])window.addEventListener(event,()=>{const el=document.getElementById('network-label');if(el)el.textContent=navigator.onLine?'آمادهٔ ثبت':'حالت آفلاین';if(state){updateRateStatus();if(event==='online')refreshDollarRate();}});
try{state=await load();const initial=location.hash.slice(1);if(SECTIONS.some(s=>s[0]===initial))tab=initial;render();window.metReady=true;refreshDollarRate();refreshMarket();refreshCalendar();setInterval(()=>{if(!document.hidden&&navigator.onLine){refreshMarket();refreshCalendar();}},300000);setInterval(()=>{if(!document.hidden)refreshDollarRate();},300000);setInterval(updateClock,1000);setInterval(()=>{if(!document.hidden&&navigator.onLine)refreshFeed(true);},60000);if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('ذخیرهٔ آفلاین برنامه فعال نشد؛ اتصال و HTTPS را بررسی کنید.'));}catch(error){window.metReady=true;root.innerHTML=`<section class="startup-error"><h1>دسترسی به دفتر معاملاتی ممکن نیست</h1><p>مجوز ذخیره‌سازی مرورگر و فضای خالی را بررسی کنید. اطلاعات موجود حذف نشده است.</p><p>${h(error.message)}</p><button class="button" onclick="location.reload()">تلاش دوباره</button></section>`;}
